def regrouper_financeurs(apps, schema_editor):
    """#790 (Q2) — les financeurs saisis action par action deviennent des
    financeurs du plan : même nom (casse et espaces ignorés) + même catégorie
    = un seul financeur ; noms différents = financeurs distincts."""
    FinanceOperation = apps.get_model('plans', 'FinanceOperation')
    Financeur = apps.get_model('plans', 'Financeur')
    plan_par_op = {}
    for chemin in _CHEMINS:
        for op_id, plan_id in (FinanceOperation.objects
                               .exclude(**{f'id_operation__{chemin}': None})
                               .values_list('id_operation_id', f'id_operation__{chemin}')):
            plan_par_op.setdefault(op_id, plan_id)
    cache = {}
    for fin in FinanceOperation.objects.filter(id_financeur__isnull=True).order_by('pk'):
        plan_id = plan_par_op.get(fin.id_operation_id)
        nom = (fin.libelle or '').strip()
        if plan_id is None or not nom:
            continue
        cle = (plan_id, ' '.join(nom.lower().split()), fin.id_categorie_id)
        if cle not in cache:
            cache[cle] = Financeur.objects.create(
                id_pg_id=plan_id, nom=nom, id_categorie_id=fin.id_categorie_id)
        fin.id_financeur = cache[cle]
        fin.save(update_fields=['id_financeur'])


